//! AgentSessionService (workbench design §4.2): one `codex app-server` process
//! per (flow, stage) session, JSON-RPC 2.0 over stdio (protocol v2 as
//! generated by `codex app-server generate-json-schema`, codex-cli 0.158).
//!
//! Responsibilities: process lifecycle (spawn / initialize / thread start or
//! resume / idle reap), one turn at a time, approval policy, event
//! normalization for the browser and a bounded transcript for reconnects.

use std::collections::{HashMap, HashSet, VecDeque};
use std::path::{Path, PathBuf};
use std::process::Stdio;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::{Arc, Mutex as StdMutex};
use std::time::{Duration, Instant};

use dashmap::DashMap;
use serde_json::{json, Value};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::process::{Child, ChildStdin, Command};
use tokio::sync::{broadcast, oneshot, Mutex, OwnedSemaphorePermit, Semaphore};

use super::model::DocType;
use crate::error::WebPlatformError;

/// Commands whose parsed actions are all in this set run without asking.
const READ_ONLY_ACTIONS: &[&str] = &["read", "listFiles", "search"];
const HISTORY_LIMIT: usize = 400;
const RPC_TIMEOUT: Duration = Duration::from_secs(60);
const USER_DECISION_TIMEOUT: Duration = Duration::from_secs(600);

#[derive(Debug, Clone)]
pub struct AgentConfig {
    /// Shell command that starts the app-server (default `codex app-server`).
    pub command: String,
    /// Extra env keys passed through (system config `codex.env_passthrough`).
    pub env_passthrough: Vec<String>,
    pub idle_timeout: Duration,
    pub turn_timeout: Duration,
    /// No event for this long during a turn = stalled.
    pub stall_timeout: Duration,
}

impl Default for AgentConfig {
    fn default() -> Self {
        Self {
            command: "codex app-server".to_string(),
            env_passthrough: Vec::new(),
            idle_timeout: Duration::from_secs(15 * 60),
            turn_timeout: Duration::from_secs(20 * 60),
            stall_timeout: Duration::from_secs(5 * 60),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Mode {
    Interactive,
    NonInteractive,
}

#[derive(Debug, Clone, serde::Serialize)]
pub struct TurnOutcome {
    /// `completed`, `interrupted`, `failed`.
    pub status: String,
    pub error: Option<String>,
}

impl TurnOutcome {
    pub fn is_ok(&self) -> bool {
        self.status == "completed"
    }
    fn failed(msg: impl Into<String>) -> Self {
        Self {
            status: "failed".to_string(),
            error: Some(msg.into()),
        }
    }
}

struct Process {
    child: Child,
    stdin: Arc<Mutex<ChildStdin>>,
    pending: Arc<DashMap<u64, oneshot::Sender<Result<Value, String>>>>,
    next_id: AtomicU64,
    alive: Arc<AtomicBool>,
    _permit: OwnedSemaphorePermit,
}

impl Process {
    async fn send(&self, msg: &Value) -> Result<(), WebPlatformError> {
        let mut line =
            serde_json::to_string(msg).map_err(|e| WebPlatformError::Internal(e.to_string()))?;
        line.push('\n');
        let mut stdin = self.stdin.lock().await;
        stdin
            .write_all(line.as_bytes())
            .await
            .map_err(|e| WebPlatformError::ExternalService(format!("codex stdin: {e}")))?;
        stdin
            .flush()
            .await
            .map_err(|e| WebPlatformError::ExternalService(format!("codex stdin: {e}")))
    }

    async fn request(&self, method: &str, params: Value) -> Result<Value, WebPlatformError> {
        let id = self.next_id.fetch_add(1, Ordering::SeqCst);
        let (tx, rx) = oneshot::channel();
        self.pending.insert(id, tx);
        self.send(&json!({"jsonrpc": "2.0", "id": id, "method": method, "params": params}))
            .await?;
        match tokio::time::timeout(RPC_TIMEOUT, rx).await {
            Ok(Ok(Ok(v))) => Ok(v),
            Ok(Ok(Err(e))) => Err(WebPlatformError::ExternalService(format!(
                "codex {method}: {e}"
            ))),
            Ok(Err(_)) => Err(WebPlatformError::ExternalService(format!(
                "codex exited during {method}"
            ))),
            Err(_) => {
                self.pending.remove(&id);
                Err(WebPlatformError::ExternalService(format!(
                    "codex {method} timed out"
                )))
            }
        }
    }
}

#[derive(Default)]
struct TurnState {
    running: bool,
    mode: Option<Mode>,
    turn_id: Option<String>,
    done: Option<oneshot::Sender<TurnOutcome>>,
    last_event: Option<Instant>,
}

/// One (flow, stage) session.
pub struct AgentSession {
    pub flow_id: i64,
    pub stage: DocType,
    cwd: PathBuf,
    /// Workspace-relative writable directory (e.g. `docs/changes/12`).
    writable_rel: String,
    developer_instructions: String,
    config: AgentConfig,
    semaphore: Arc<Semaphore>,
    process: Mutex<Option<Process>>,
    thread_id: StdMutex<Option<String>>,
    turn: StdMutex<TurnState>,
    /// Paths (workspace-relative) the AI is modifying in the current turn.
    locked: StdMutex<HashSet<String>>,
    /// fileChange itemId -> workspace-relative paths.
    item_paths: StdMutex<HashMap<String, Vec<String>>>,
    history: StdMutex<VecDeque<Value>>,
    pending_user: DashMap<String, oneshot::Sender<Value>>,
    events: broadcast::Sender<Value>,
    last_activity: StdMutex<Instant>,
}

impl AgentSession {
    pub fn subscribe(&self) -> broadcast::Receiver<Value> {
        self.events.subscribe()
    }

    pub fn history(&self) -> Vec<Value> {
        self.history.lock().unwrap().iter().cloned().collect()
    }

    pub fn is_running(&self) -> bool {
        self.turn.lock().unwrap().running
    }

    pub fn running_mode(&self) -> Option<Mode> {
        let t = self.turn.lock().unwrap();
        t.running.then_some(t.mode).flatten()
    }

    pub fn locked_paths(&self) -> HashSet<String> {
        self.locked.lock().unwrap().clone()
    }

    pub fn thread_id(&self) -> Option<String> {
        self.thread_id.lock().unwrap().clone()
    }

    pub fn set_thread_id(&self, id: Option<String>) {
        *self.thread_id.lock().unwrap() = id;
    }

    pub fn has_process(&self) -> bool {
        self.process.try_lock().map(|p| p.is_some()).unwrap_or(true)
    }

    /// Publish an event to subscribers and the transcript. Text deltas are
    /// folded into one history entry per item so reconnects replay the full
    /// message even when no completed event follows (verify r2 N2).
    pub fn emit(&self, event: Value) {
        let kind = event.get("type").and_then(|v| v.as_str()).unwrap_or("");
        if kind == "message_delta" || kind == "reasoning_delta" {
            let mut h = self.history.lock().unwrap();
            let item = event.get("itemId").cloned().unwrap_or(Value::Null);
            let delta = event.get("delta").and_then(|d| d.as_str()).unwrap_or("");
            let found = h.iter_mut().rev().take(50).find(|e| {
                e.get("type").and_then(|t| t.as_str()) == Some(kind)
                    && e.get("itemId") == Some(&item)
            });
            match found {
                Some(e) => {
                    let cur = e
                        .get("delta")
                        .and_then(|d| d.as_str())
                        .unwrap_or("")
                        .to_string();
                    e["delta"] = Value::String(cur + delta);
                }
                None => h.push_back(event.clone()),
            }
            while h.len() > HISTORY_LIMIT {
                h.pop_front();
            }
        } else if kind != "command_output" && kind != "diff" {
            let mut h = self.history.lock().unwrap();
            h.push_back(event.clone());
            while h.len() > HISTORY_LIMIT {
                h.pop_front();
            }
        }
        let _ = self.events.send(event);
    }

    /// Answer a pending approval / user-input request from the browser.
    pub fn answer(&self, request_id: &str, answer: Value) -> bool {
        match self.pending_user.remove(request_id) {
            Some((_, tx)) => tx.send(answer).is_ok(),
            None => false,
        }
    }

    fn touch(&self) {
        *self.last_activity.lock().unwrap() = Instant::now();
    }

    pub fn idle_for(&self) -> Duration {
        self.last_activity.lock().unwrap().elapsed()
    }

    /// Kill the app-server process (idle reap / shutdown). The thread id is
    /// kept so the next turn resumes the conversation.
    pub async fn stop(&self) {
        let mut guard = self.process.lock().await;
        if let Some(mut p) = guard.take() {
            p.alive.store(false, Ordering::SeqCst);
            let _ = p.child.start_kill();
            let _ = tokio::time::timeout(Duration::from_secs(5), p.child.wait()).await;
        }
    }

    /// Workspace-relative form of a path reported by codex. Absolute paths
    /// are compared after resolving symlinks (e.g. macOS `/var` → `/private/var`);
    /// paths outside the workspace are returned absolute (never writable).
    fn rel_path(&self, p: &str) -> String {
        let path = Path::new(p);
        if !path.is_absolute() {
            return p.trim_start_matches("./").to_string();
        }
        if let Ok(r) = path.strip_prefix(&self.cwd) {
            return r.to_string_lossy().to_string();
        }
        let real_cwd = self.cwd.canonicalize().unwrap_or_else(|_| self.cwd.clone());
        let real = canonical_lenient(path);
        real.strip_prefix(&real_cwd)
            .map(|r| r.to_string_lossy().to_string())
            .unwrap_or_else(|_| p.to_string())
    }

    fn in_writable(&self, rel: &str) -> bool {
        if rel.split('/').any(|seg| seg == ".." || seg == ".git") {
            return false;
        }
        rel == self.writable_rel || rel.starts_with(&format!("{}/", self.writable_rel))
    }

    async fn ensure_process(self: &Arc<Self>) -> Result<(), WebPlatformError> {
        let mut guard = self.process.lock().await;
        if let Some(p) = guard.as_ref() {
            if p.alive.load(Ordering::SeqCst) {
                return Ok(());
            }
        }
        *guard = None;
        let permit =
            self.semaphore.clone().try_acquire_owned().map_err(|_| {
                WebPlatformError::Conflict("AI 会话已达上限，请稍后再试".to_string())
            })?;

        let mut cmd = Command::new("sh");
        cmd.arg("-c")
            .arg(&self.config.command)
            .current_dir(&self.cwd)
            .env_clear()
            .envs(crate::process_manager::spawn::filter_worker_env(
                std::env::vars(),
                &self.config.env_passthrough,
            ))
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .kill_on_drop(true);
        #[cfg(unix)]
        cmd.process_group(0);
        let mut child = cmd
            .spawn()
            .map_err(|e| WebPlatformError::ExternalService(format!("无法启动 codex：{e}")))?;
        let stdin = child.stdin.take().expect("piped stdin");
        let stdout = child.stdout.take().expect("piped stdout");
        let stderr = child.stderr.take().expect("piped stderr");

        let process = Process {
            child,
            stdin: Arc::new(Mutex::new(stdin)),
            pending: Arc::new(DashMap::new()),
            next_id: AtomicU64::new(1),
            alive: Arc::new(AtomicBool::new(true)),
            _permit: permit,
        };

        // stderr: log only.
        tokio::spawn(async move {
            let mut lines = BufReader::new(stderr).lines();
            while let Ok(Some(line)) = lines.next_line().await {
                tracing::debug!(target: "sdlc_codex", "{}", line);
            }
        });

        // stdout reader.
        let session = Arc::downgrade(self);
        let pending = process.pending.clone();
        let stdin = process.stdin.clone();
        let alive = process.alive.clone();
        tokio::spawn(async move {
            let mut lines = BufReader::new(stdout).lines();
            while let Ok(Some(line)) = lines.next_line().await {
                let Ok(msg) = serde_json::from_str::<Value>(line.trim()) else {
                    continue;
                };
                let Some(session) = session.upgrade() else {
                    break;
                };
                session.on_message(msg, &pending, &stdin).await;
            }
            alive.store(false, Ordering::SeqCst);
            for entry in pending.iter() {
                let _ = entry.key();
            }
            pending.clear();
            if let Some(session) = session.upgrade() {
                session.finish_turn(TurnOutcome::failed("codex app-server 已退出"));
            }
        });

        // Handshake.
        process
            .request(
                "initialize",
                json!({"clientInfo": {"name": "symphony-web", "title": "Symphony Workbench", "version": env!("CARGO_PKG_VERSION")}}),
            )
            .await?;
        process
            .send(&json!({"jsonrpc": "2.0", "method": "initialized"}))
            .await?;

        let cwd = self.cwd.to_string_lossy().to_string();
        let base = json!({
            "cwd": cwd,
            "approvalPolicy": "on-request",
            "sandbox": "workspace-write",
            "developerInstructions": self.developer_instructions,
        });
        let existing = self.thread_id();
        let mut thread_id = None;
        if let Some(tid) = existing {
            let mut p = base.clone();
            p["threadId"] = json!(tid);
            match process.request("thread/resume", p).await {
                Ok(v) => thread_id = extract_thread_id(&v).or(Some(tid)),
                Err(e) => tracing::warn!("thread/resume failed, starting new thread: {e}"),
            }
        }
        if thread_id.is_none() {
            let v = process.request("thread/start", base).await?;
            thread_id = extract_thread_id(&v);
        }
        let thread_id = thread_id.ok_or_else(|| {
            WebPlatformError::ExternalService("codex 未返回 thread id".to_string())
        })?;
        self.set_thread_id(Some(thread_id));
        *guard = Some(process);
        Ok(())
    }

    async fn on_message(
        self: &Arc<Self>,
        msg: Value,
        pending: &Arc<DashMap<u64, oneshot::Sender<Result<Value, String>>>>,
        stdin: &Arc<Mutex<ChildStdin>>,
    ) {
        let method = msg
            .get("method")
            .and_then(|m| m.as_str())
            .map(str::to_string);
        let id = msg.get("id").cloned();
        match (method, id) {
            (None, Some(id)) => {
                if let Some(n) = id.as_u64() {
                    if let Some((_, tx)) = pending.remove(&n) {
                        let r = match msg.get("error") {
                            Some(e) => Err(e
                                .get("message")
                                .and_then(|m| m.as_str())
                                .unwrap_or("error")
                                .to_string()),
                            None => Ok(msg.get("result").cloned().unwrap_or(Value::Null)),
                        };
                        let _ = tx.send(r);
                    }
                }
            }
            (Some(method), Some(id)) => {
                let session = self.clone();
                let stdin = stdin.clone();
                let params = msg.get("params").cloned().unwrap_or(Value::Null);
                tokio::spawn(async move {
                    let response = session.handle_server_request(&method, &params, &id).await;
                    let mut line = serde_json::to_string(&response).unwrap_or_default();
                    line.push('\n');
                    let mut w = stdin.lock().await;
                    let _ = w.write_all(line.as_bytes()).await;
                    let _ = w.flush().await;
                });
            }
            (Some(method), None) => {
                let params = msg.get("params").cloned().unwrap_or(Value::Null);
                self.on_notification(&method, &params);
            }
            _ => {}
        }
    }

    fn on_notification(&self, method: &str, params: &Value) {
        self.touch();
        self.turn.lock().unwrap().last_event = Some(Instant::now());
        match method {
            "turn/started" => {
                let turn_id = params.pointer("/turn/id").and_then(|v| v.as_str()).map(str::to_string);
                self.turn.lock().unwrap().turn_id = turn_id.clone();
                self.emit(json!({"type": "turn_started", "turnId": turn_id}));
            }
            "turn/completed" => {
                let status = params
                    .pointer("/turn/status")
                    .and_then(|v| v.as_str())
                    .unwrap_or("completed")
                    .to_string();
                let error = params
                    .pointer("/turn/error/message")
                    .and_then(|v| v.as_str())
                    .map(str::to_string);
                self.finish_turn(TurnOutcome { status, error });
            }
            "item/agentMessage/delta" => self.emit(json!({
                "type": "message_delta", "itemId": params.get("itemId"), "delta": params.get("delta")
            })),
            "item/reasoning/summaryTextDelta" | "item/reasoning/textDelta" => self.emit(json!({
                "type": "reasoning_delta", "itemId": params.get("itemId"), "delta": params.get("delta")
            })),
            "item/commandExecution/outputDelta" => self.emit(json!({
                "type": "command_output", "itemId": params.get("itemId"), "delta": params.get("delta")
            })),
            "turn/diff/updated" => self.emit(json!({"type": "diff", "diff": params.get("diff")})),
            "item/started" | "item/completed" => {
                let item = params.get("item").cloned().unwrap_or(Value::Null);
                if item.get("type").and_then(|t| t.as_str()) == Some("fileChange") {
                    let paths: Vec<String> = item
                        .get("changes")
                        .and_then(|c| c.as_array())
                        .map(|a| {
                            a.iter()
                                .filter_map(|c| c.get("path").and_then(|p| p.as_str()))
                                .map(|p| self.rel_path(p))
                                .collect()
                        })
                        .unwrap_or_default();
                    if let Some(id) = item.get("id").and_then(|i| i.as_str()) {
                        self.item_paths.lock().unwrap().insert(id.to_string(), paths.clone());
                    }
                    let mut locked = self.locked.lock().unwrap();
                    for p in paths.into_iter().filter(|p| self.in_writable(p)) {
                        locked.insert(p);
                    }
                }
                let phase = if method == "item/started" { "started" } else { "completed" };
                if let Some(compact) = compact_item(&item, |p| self.rel_path(p)) {
                    self.emit(json!({"type": "item", "phase": phase, "item": compact}));
                }
            }
            "error" => self.emit(json!({
                "type": "error",
                "message": params.pointer("/error/message").or_else(|| params.get("message"))
            })),
            _ => {}
        }
    }

    async fn handle_server_request(
        self: &Arc<Self>,
        method: &str,
        params: &Value,
        id: &Value,
    ) -> Value {
        let mode = self
            .turn
            .lock()
            .unwrap()
            .mode
            .unwrap_or(Mode::NonInteractive);
        let ok = |result: Value| json!({"jsonrpc": "2.0", "id": id, "result": result});
        match method {
            "item/fileChange/requestApproval" => {
                let item_id = params.get("itemId").and_then(|v| v.as_str()).unwrap_or("");
                let paths = self
                    .item_paths
                    .lock()
                    .unwrap()
                    .get(item_id)
                    .cloned()
                    .unwrap_or_default();
                let mut outside: Vec<String> = paths
                    .iter()
                    .filter(|p| !self.in_writable(p))
                    .cloned()
                    .collect();
                // Unknown paths (no item/started seen) or a request for extra
                // write roots are never approved (verify A I-2).
                if paths.is_empty() {
                    outside.push("<未知路径>".to_string());
                }
                if let Some(root) = params.get("grantRoot").and_then(|v| v.as_str()) {
                    outside.push(format!("grantRoot={root}"));
                }
                let decision = if outside.is_empty() {
                    "accept"
                } else {
                    "decline"
                };
                if !outside.is_empty() {
                    self.emit(json!({"type": "notice", "level": "warning",
                        "message": format!("已拒绝 AI 修改可写目录以外的文件：{}", outside.join(", "))}));
                }
                ok(json!({"decision": decision}))
            }
            "item/commandExecution/requestApproval" => {
                let read_only = params
                    .get("commandActions")
                    .and_then(|a| a.as_array())
                    .map(|a| {
                        !a.is_empty()
                            && a.iter().all(|x| {
                                x.get("type")
                                    .and_then(|t| t.as_str())
                                    .is_some_and(|t| READ_ONLY_ACTIONS.contains(&t))
                            })
                    })
                    .unwrap_or(false);
                if read_only {
                    return ok(json!({"decision": "accept"}));
                }
                if mode == Mode::NonInteractive {
                    self.emit(json!({"type": "notice", "level": "info",
                        "message": format!("非交互起草：已自动拒绝命令 {}", params.get("command").and_then(|c| c.as_str()).unwrap_or(""))}));
                    return ok(json!({"decision": "decline"}));
                }
                let answer = self
                    .ask_user(json!({
                        "type": "approval_request",
                        "kind": "command",
                        "command": params.get("command"),
                        "cwd": params.get("cwd"),
                        "reason": params.get("reason"),
                    }))
                    .await;
                let decision = match answer.get("decision").and_then(|d| d.as_str()) {
                    Some("accept") => "accept",
                    _ => "decline",
                };
                ok(json!({"decision": decision}))
            }
            "item/tool/requestUserInput" => {
                if mode == Mode::NonInteractive {
                    return ok(json!({"answers": {}}));
                }
                let answer = self
                    .ask_user(
                        json!({"type": "user_input_request", "questions": params.get("questions")}),
                    )
                    .await;
                let answers = answer.get("answers").cloned().unwrap_or_else(|| json!({}));
                ok(json!({"answers": answers}))
            }
            // Legacy v1 approval requests.
            "applyPatchApproval" | "execCommandApproval" => ok(json!({"decision": "denied"})),
            _ => {
                json!({"jsonrpc": "2.0", "id": id, "error": {"code": -32601, "message": format!("{method} is not supported by Symphony")}})
            }
        }
    }

    async fn ask_user(&self, mut event: Value) -> Value {
        let request_id = uuid::Uuid::new_v4().to_string();
        let (tx, rx) = oneshot::channel();
        self.pending_user.insert(request_id.clone(), tx);
        event["requestId"] = json!(request_id);
        self.emit(event);
        let answer = tokio::time::timeout(USER_DECISION_TIMEOUT, rx).await;
        self.pending_user.remove(&request_id);
        self.emit(json!({"type": "request_resolved", "requestId": request_id}));
        answer.ok().and_then(|r| r.ok()).unwrap_or(Value::Null)
    }

    fn finish_turn(&self, outcome: TurnOutcome) {
        let mut t = self.turn.lock().unwrap();
        if let Some(tx) = t.done.take() {
            let _ = tx.send(outcome);
        }
    }

    /// Steer the running turn with extra input (`turn/steer`).
    pub async fn steer(self: &Arc<Self>, text: &str) -> Result<(), WebPlatformError> {
        let (turn_id, thread_id) = {
            let t = self.turn.lock().unwrap();
            (t.turn_id.clone(), self.thread_id())
        };
        let (Some(turn_id), Some(thread_id)) = (turn_id, thread_id) else {
            return Err(WebPlatformError::Conflict(
                "当前没有进行中的 AI 回合".into(),
            ));
        };
        let guard = self.process.lock().await;
        let p = guard
            .as_ref()
            .ok_or_else(|| WebPlatformError::Conflict("AI 会话未运行".into()))?;
        p.request(
            "turn/steer",
            json!({"threadId": thread_id, "expectedTurnId": turn_id, "input": [{"type": "text", "text": text}]}),
        )
        .await
        .map(|_| ())
    }

    /// Interrupt the running turn.
    pub async fn interrupt(self: &Arc<Self>) -> Result<(), WebPlatformError> {
        let (turn_id, thread_id) = {
            let t = self.turn.lock().unwrap();
            (t.turn_id.clone(), self.thread_id())
        };
        let guard = self.process.lock().await;
        if let (Some(p), Some(turn_id), Some(thread_id)) = (guard.as_ref(), turn_id, thread_id) {
            let _ = p
                .request(
                    "turn/interrupt",
                    json!({"threadId": thread_id, "turnId": turn_id}),
                )
                .await;
        }
        Ok(())
    }

    /// Mark the session busy; `false` when a turn is already running.
    pub fn try_begin(&self, mode: Mode) -> bool {
        let mut t = self.turn.lock().unwrap();
        if t.running {
            return false;
        }
        t.running = true;
        t.mode = Some(mode);
        t.turn_id = None;
        true
    }

    /// Release the process after a non-interactive draft so the session
    /// quota is not held until the idle reaper runs (verify C #3). The
    /// thread id is kept; the next turn resumes it.
    pub async fn release_after_draft(&self) {
        self.stop().await;
    }

    /// Release the session after a turn (also clears per-turn locks).
    pub fn end(&self) {
        let mut t = self.turn.lock().unwrap();
        t.running = false;
        t.mode = None;
        t.turn_id = None;
        t.done = None;
        self.locked.lock().unwrap().clear();
        self.item_paths.lock().unwrap().clear();
    }

    /// Run one turn. Caller must have called `try_begin` and must call `end`.
    pub async fn run_turn(self: &Arc<Self>, text: &str) -> TurnOutcome {
        self.touch();
        if let Err(e) = self.ensure_process().await {
            return TurnOutcome::failed(e.to_string());
        }
        let (tx, rx) = oneshot::channel();
        {
            let mut t = self.turn.lock().unwrap();
            t.done = Some(tx);
            t.last_event = Some(Instant::now());
        }
        let thread_id = self.thread_id().unwrap_or_default();
        let start = {
            let guard = self.process.lock().await;
            match guard.as_ref() {
                Some(p) => {
                    p.request(
                        "turn/start",
                        json!({
                            "threadId": thread_id,
                            "cwd": self.cwd.to_string_lossy(),
                            "input": [{"type": "text", "text": text}],
                        }),
                    )
                    .await
                }
                None => Err(WebPlatformError::ExternalService("codex 未运行".into())),
            }
        };
        match start {
            Ok(v) => {
                if let Some(id) = v.pointer("/turn/id").and_then(|i| i.as_str()) {
                    self.turn.lock().unwrap().turn_id = Some(id.to_string());
                }
            }
            Err(e) => return TurnOutcome::failed(e.to_string()),
        }

        let started = Instant::now();
        let mut rx = rx;
        loop {
            match tokio::time::timeout(Duration::from_secs(5), &mut rx).await {
                Ok(Ok(outcome)) => {
                    self.touch();
                    return outcome;
                }
                Ok(Err(_)) => return TurnOutcome::failed("AI 回合异常结束"),
                Err(_) => {
                    let last = self.turn.lock().unwrap().last_event.unwrap_or(started);
                    let waiting_user = !self.pending_user.is_empty();
                    if started.elapsed() > self.config.turn_timeout
                        || (!waiting_user && last.elapsed() > self.config.stall_timeout)
                    {
                        let _ = self.interrupt().await;
                        self.stop().await;
                        return TurnOutcome::failed("AI 回合超时，已终止");
                    }
                }
            }
        }
    }
}

/// Canonicalize the deepest existing ancestor and re-append the rest, so
/// not-yet-created files still resolve. `..` segments are rejected upstream
/// by `in_writable` (they never start with the writable prefix).
fn canonical_lenient(path: &Path) -> PathBuf {
    let mut existing = path.to_path_buf();
    let mut tail = Vec::new();
    while !existing.exists() {
        match existing.file_name() {
            Some(n) => tail.push(n.to_os_string()),
            None => break,
        }
        if !existing.pop() {
            break;
        }
    }
    let mut out = existing.canonicalize().unwrap_or(existing);
    for t in tail.into_iter().rev() {
        out.push(t);
    }
    out
}

fn extract_thread_id(v: &Value) -> Option<String> {
    v.pointer("/thread/id")
        .or_else(|| v.get("threadId"))
        .and_then(|t| t.as_str())
        .map(str::to_string)
}

/// Compact a ThreadItem for the browser.
fn compact_item(item: &Value, rel: impl Fn(&str) -> String) -> Option<Value> {
    let kind = item.get("type")?.as_str()?;
    let id = item.get("id");
    let truncate = |s: &str| -> String { s.chars().take(4000).collect() };
    Some(match kind {
        "agentMessage" => json!({"id": id, "kind": "message", "text": item.get("text")}),
        "reasoning" => json!({"id": id, "kind": "reasoning", "summary": item.get("summary")}),
        "commandExecution" => json!({
            "id": id, "kind": "command",
            "command": item.get("command"),
            "status": item.get("status"),
            "exitCode": item.get("exitCode"),
            "output": item.get("aggregatedOutput").and_then(|o| o.as_str()).map(truncate),
        }),
        "fileChange" => json!({
            "id": id, "kind": "file_change",
            "status": item.get("status"),
            "paths": item.get("changes").and_then(|c| c.as_array()).map(|a| a.iter()
                .filter_map(|c| c.get("path").and_then(|p| p.as_str()).map(&rel)).collect::<Vec<_>>()),
        }),
        "userMessage" => return None,
        other => json!({"id": id, "kind": other}),
    })
}

/// Registry of sessions + global concurrency limit.
pub struct AgentManager {
    sessions: DashMap<(i64, DocType), Arc<AgentSession>>,
    semaphore: Arc<Semaphore>,
    config: StdMutex<AgentConfig>,
}

pub struct SessionSpec {
    pub flow_id: i64,
    pub stage: DocType,
    pub cwd: PathBuf,
    pub writable_rel: String,
    pub developer_instructions: String,
    pub thread_id: Option<String>,
}

impl AgentManager {
    pub fn new(config: AgentConfig, max_sessions: usize) -> Arc<Self> {
        let mgr = Arc::new(Self {
            sessions: DashMap::new(),
            semaphore: Arc::new(Semaphore::new(max_sessions.max(1))),
            config: StdMutex::new(config),
        });
        // Idle reaper.
        let weak = Arc::downgrade(&mgr);
        tokio::spawn(async move {
            loop {
                tokio::time::sleep(Duration::from_secs(30)).await;
                let Some(mgr) = weak.upgrade() else { break };
                let idle = mgr.config.lock().unwrap().idle_timeout;
                let victims: Vec<Arc<AgentSession>> = mgr
                    .sessions
                    .iter()
                    .filter(|s| !s.is_running() && s.idle_for() > idle)
                    .map(|s| s.value().clone())
                    .collect();
                for s in victims {
                    s.stop().await;
                }
            }
        });
        mgr
    }

    pub fn set_env_passthrough(&self, keys: Vec<String>) {
        self.config.lock().unwrap().env_passthrough = keys;
    }

    pub fn get_or_create(&self, spec: SessionSpec) -> Arc<AgentSession> {
        let key = (spec.flow_id, spec.stage);
        if let Some(s) = self.sessions.get(&key) {
            return s.clone();
        }
        let (events, _) = broadcast::channel(1024);
        let session = Arc::new(AgentSession {
            flow_id: spec.flow_id,
            stage: spec.stage,
            cwd: spec.cwd,
            writable_rel: spec.writable_rel,
            developer_instructions: spec.developer_instructions,
            config: self.config.lock().unwrap().clone(),
            semaphore: self.semaphore.clone(),
            process: Mutex::new(None),
            thread_id: StdMutex::new(spec.thread_id),
            turn: StdMutex::new(TurnState::default()),
            locked: StdMutex::new(HashSet::new()),
            item_paths: StdMutex::new(HashMap::new()),
            history: StdMutex::new(VecDeque::new()),
            pending_user: DashMap::new(),
            events,
            last_activity: StdMutex::new(Instant::now()),
        });
        self.sessions.entry(key).or_insert(session).clone()
    }

    pub fn get(&self, flow_id: i64, stage: DocType) -> Option<Arc<AgentSession>> {
        self.sessions.get(&(flow_id, stage)).map(|s| s.clone())
    }

    pub fn flow_sessions(&self, flow_id: i64) -> Vec<Arc<AgentSession>> {
        self.sessions
            .iter()
            .filter(|e| e.key().0 == flow_id)
            .map(|e| e.value().clone())
            .collect()
    }

    /// Paths locked by any running session of a flow.
    pub fn locked_paths(&self, flow_id: i64) -> HashSet<String> {
        self.flow_sessions(flow_id)
            .iter()
            .filter(|s| s.is_running())
            .flat_map(|s| s.locked_paths())
            .collect()
    }

    pub async fn remove_flow(&self, flow_id: i64) {
        for s in self.flow_sessions(flow_id) {
            s.stop().await;
            self.sessions.remove(&(flow_id, s.stage));
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn compact_items() {
        let cmd = json!({"type": "commandExecution", "id": "1", "command": "ls", "status": "completed", "aggregatedOutput": "a"});
        let c = compact_item(&cmd, |p| p.to_string()).unwrap();
        assert_eq!(c["kind"], "command");
        let fc = json!({"type": "fileChange", "id": "2", "status": "completed", "changes": [{"path": "/w/docs/x.md", "diff": "", "kind": {"type": "add"}}]});
        let c = compact_item(&fc, |p| p.trim_start_matches("/w/").to_string()).unwrap();
        assert_eq!(c["paths"][0], "docs/x.md");
        assert!(
            compact_item(&json!({"type": "userMessage", "id": "3"}), |p| p
                .to_string())
            .is_none()
        );
    }

    #[test]
    fn thread_id_extraction() {
        assert_eq!(
            extract_thread_id(&json!({"thread": {"id": "t1"}})),
            Some("t1".into())
        );
        assert_eq!(extract_thread_id(&json!({})), None);
    }
}
